  "similar_words": "නීලුප්පලං, දක්ඛපුරිසො, මහාපුරිසො, මහබ්බලං, අමච්චපුත්තො, පුඞ්කොකිලො, පුන්නාගො, සාරිපුත්තත්ථෙරො, ගුණධනං, බහුලීකතං, අබ්‍රාහ්මණො, අධම්මො, අනස්සො, අනරියො, කදන්නං, කදසනං, කාලවණං, කාපුරිසො, පාවචනං ආදිය",
  "notes": [
   "කම්මධාරය සමාසයෙන් සෑදුණු රූපය (ඛත්තියකඤ්ඤා) පද සාධන ඛණ්ඩයේ නාම විභක්ති රීති අනුව වරනැඟේ; සමාස සාධනය ප්‍රකෘති සාධනයෙහි දක්වා ඇත."
  ],
